% Feature extraction: two adaptive differentiators -> counter -> NN.
% Replaces the failed direct branch-cancellation version.
%
% THREE CORE REACTIONS PER DIFFERENTIATOR (effective low-substrate rates):
%   X_j -> M_j           a_j*X_j
%   M_j -> Y_j           b_j*M_j
%   X_j + Y_j -> W_j     c_j*X_j*Y_j
% X_1 = m_in is externally imposed/buffered; its depletion is not modeled.
% X_2 = Y_1. M_j stores history; Y_j is a positive readout.
% An isolated stage has Y_j,SS = a_j/c_j for positive constant input.
% Its small-signal output deviation is an INVERTED filtered derivative.
% Stage 1 rises during a falling input. Stage 2 DIPS while stage 1 rises.
%
% Default coupling is substrate-consuming: stage-2 production AND clearance
% consume Y_1. Both loading terms are included in dY_1/dt. Weak loading is
% designed at the initial input; exact first-stage adaptation is then lost.
% The alternative 'regulatory' setting treats Y_1 as a nonconsumed regulator.
% It needs catalytic/regulatory biochemical realizations, not literal Y_1
% conversion. Neither setting proves that six native reactions exist.
%
% COUNTER INTERFACE: a buffered precursor produces C through an enzyme
% inhibited by Y_2 and, optionally, activated by Y_1. Hill regulation is an
% explicit design assumption, not a verified intracellular mechanism.
% NO diagnostic subtraction, clipping, or digital derivative feeds any
% physical reaction. Such operations appear ONLY in diagnostics/plots.
% The counter is the legacy resettable analog accumulator, NOT an exact
% elapsed-time timer. Its basal fluxes are balanced at initialization.
% Six is the differentiator-core count. Counter supply, regulation, buffered
% precursors, cofactors and the NN are additional implementation requirements.
%
% All concentrations: mM. Time: seconds. a,b: 1/s; c: 1/(mM*s).
% No EC identity is assigned to the new differentiator reactions. Effective
% a,b,c must be fitted from actual enzyme kinetics in the operating regime.
% In particular, a bisubstrate rate need not have c=Vmax/(Km_X*Km_Y).
% Input must stay positive: at zero input the adaptive clearance stops.
% The 13 existing figure roles are retained with labels for the new states.
% Parameters.m and Dataset_cell2cell.mat are used if available. Otherwise
% an explicitly identified synthetic demonstration runs without dependencies.

clc;
clearvars;
close all;

scriptDir = fileparts(mfilename('fullpath'));
if isempty(scriptDir), scriptDir = pwd; end
fontsize = 15;
dt0 = 0.1;
parametersFile = locate_local_file('Parameters.m', scriptDir);
if ~isempty(parametersFile)
    run(parametersFile);
end
assert(isscalar(dt0) && isfinite(dt0) && dt0 > 0, 'dt0 must be positive.');
dtInput = dt0;

% ================= USER CALIBRATION =================
row = 1;
gain_in = 1e-4;                 % mM/vesicle: 500 vesicles -> 0.05 mM
coupling_mode = 'consuming';    % 'consuming' or 'regulatory'; see header
USE_DEMO_IF_DATA_MISSING = true;
RUN_SELF_CHECKS = true;

% These are illustrative design targets, not measured enzyme constants.
tau_M1 = 30;                   % s, first-stage memory
tau_Y1 = 3;                    % s, first-stage output relaxation at u_ref
tau_M2 = 10;                   % s, second-stage memory
tau_Y2 = 1;                    % s, second-stage relaxation at Y1_ref
Y1_ref = 1e-2;                 % mM, physical stage-1 basal concentration
Y2_ref = 1e-6;                 % mM, smaller to reduce upstream loading

% Counter regulation. Finite Hill exponents imply basal activity.
% Increasing cooperativity is NOT a substitute for verifying a mechanism.
use_first_stage_activation = true; % soft Y1 regulation, not a Boolean gate
n_gate1 = 4;
n_gate2 = 8;
gate_reference_rel_tol = 1e-6; % digital diagnostic only; not a rate threshold

% -------- Received signal / dataset --------
datasetFile = locate_local_file('Dataset_cell2cell.mat', scriptDir);
isDemo = isempty(datasetFile);
if ~isDemo %[output:group:527a987b]
    loadedData = load(datasetFile, 'Dataset');
    assert(isfield(loadedData, 'Dataset') && istable(loadedData.Dataset), ...
        'Dataset_cell2cell.mat must contain a table named Dataset.');
    Dataset = rmmissing(loadedData.Dataset);
    assert(width(Dataset) >= 3 && height(Dataset) >= 1, 'Dataset is empty.');
    dist = table2array(Dataset(:,1));
    vesicles = table2array(Dataset(:,2:end));
    fprintf('Input: Dataset_cell2cell.mat, row %d.\n', row); %[output:249923db]
else
    assert(USE_DEMO_IF_DATA_MISSING, ...
        'Dataset_cell2cell.mat is missing. Place it beside this script.');
    demoTime = 0:dtInput:9000;
    transition = @(tc,w) 0.5*(1+tanh((demoTime-tc)/w));
    baseSignal = 500 - 25*transition(25,5) ...
                     - 25*transition(2400,60) ...
                     - 25*transition(5200,100);
    vesicles = [baseSignal; 0.98*baseSignal; 0.96*baseSignal];
    dist = [2; 4; 6]*1e-6;
    fprintf('DEMONSTRATION INPUT: dataset missing; synthetic falling transitions.\n');
end %[output:group:527a987b]
assert(row >= 1 && row <= size(vesicles,1) && row == floor(row), ...
    'Selected row is outside the dataset.');
assert(isnumeric(vesicles) && all(isfinite(vesicles(:))), ...
    'Vesicle data must be finite numeric values.');
vesicleInput = vesicles(row,:).';
t = (0:numel(vesicleInput)-1)'*dtInput;
m_in = gain_in*vesicleInput;
N = numel(t);
assert(N >= 3 && all(m_in > 0), ...
    ['This adaptive design requires at least three samples and strictly ' ...
     'positive input. Do not silently add a floor to zero input.']);
u_ref = m_in(1);
% Original digital feature variables, now with slope in vesicles/second.
slope = diff(vesicles,1,2)/dtInput;
[peak,loc] = min(slope,[],2);
peakTime = (loc-1)*dtInput;
assert(all(isfinite([tau_M1,tau_Y1,tau_M2,tau_Y2,Y1_ref,Y2_ref])) && ...
    all([tau_M1,tau_Y1,tau_M2,tau_Y2,Y1_ref,Y2_ref] > 0), ...
    'Memory times, relaxation times and basal concentrations must be positive.');
assert(tau_M1 > tau_Y1 && tau_M2 > tau_Y2, ...
    'Choose each memory time longer than its output relaxation time.');

% -------- Calibrate two stages at the operating concentrations --------
p.b1 = 1/tau_M1;
p.c1 = 1/(u_ref*tau_Y1);
p.b2 = 1/tau_M2;
p.c2 = 1/(Y1_ref*tau_Y2);
p.a2 = p.c2*Y2_ref;
p.consume_interstage = strcmpi(coupling_mode, 'consuming');
assert(p.consume_interstage || strcmpi(coupling_mode, 'regulatory'), ...
    'coupling_mode must be consuming or regulatory.');

% Compensate the INITIAL steady load so Y1(0) = Y1_ref exactly.
% This does not compensate the load over arbitrary input concentrations.
p.a1 = Y1_ref*(p.c1*u_ref + 2*p.consume_interstage*p.a2)/u_ref;
p.Y10 = Y1_ref;
p.Y20 = Y2_ref;
p.u0 = u_ref;
p.tauM1 = tau_M1;
p.tauY1 = tau_Y1;
p.tauM2 = tau_M2;
p.tauY2 = tau_Y2;
p.use_first_stage_activation = use_first_stage_activation;
p.Kgate1 = Y1_ref;
p.Kgate2 = Y2_ref;
p.ngate1 = n_gate1;
p.ngate2 = n_gate2;
loading_ratio = 2*p.a2/(p.c1*min(m_in));
fprintf('Cascade: %s coupling; maximum equilibrium load ratio = %.4g.\n', ... %[output:group:60cc53c2] %[output:3fc1bf9f]
    coupling_mode, p.consume_interstage*loading_ratio); %[output:group:60cc53c2] %[output:3fc1bf9f]
if p.consume_interstage && loading_ratio > 0.05
    warning('AdaptiveCascade:Loading', ...
        ['Stage-2 loading is appreciable. Reduce Y2_ref, slow stage 2, ' ...
         'or use a verified nonconsuming regulatory connection.']);
end
fprintf('Effective rates: a1=%.4g, b1=%.4g, c1=%.4g; a2=%.4g, b2=%.4g, c2=%.4g.\n', ... %[output:group:03c2fa83] %[output:16813bd1]
    p.a1,p.b1,p.c1,p.a2,p.b2,p.c2); %[output:group:03c2fa83] %[output:16813bd1]

% -------- Counter: retained activity examples, corrected descriptions --------
% Legacy SA/MW examples below do not validate enzyme mappings for this design.
% Cp: buffered precursor -> C; gate controls active enzyme fraction.
E_Cp = 1e-3; SA_Cp = 10^0.5; MW_Cp = 75;
kcat_Cp = SA_Cp*MW_Cp/60;
p.VCp = kcat_Cp*E_Cp;
% Cr: regulated depletion of reset substrate Cs -> products.
E_Cr = 1e-3; SA_Cr = 10^1.5; MW_Cr = 75;
kcat_Cr = SA_Cr*MW_Cr/60;
p.VCr = kcat_Cr*E_Cr;
p.KCrCs = 10^0.5;
% Cg: C + Cs -> products, clearing the accumulated concentration.
E_Cg = 1; SA_Cg = 10^1.5; MW_Cg = 275;
kcat_Cg = SA_Cg*MW_Cg/60;
p.VCg = kcat_Cg*E_Cg;
p.KCgc = 10^0.5;
p.KCgCs = 10^0.5;
p.Csbase = 0.01;
p.ksupply = 1;

% -------- Neural network: original Hill production / decay equations --------
p.VNi = 1; p.KNi = 0.1; p.nNi = 2;
p.VNa = 1; p.KNa = 0.1; p.nNa = 2;
p.VNb = 1; p.KNb = 0.1; p.nNb = 2;
p.VNo = 1; p.KNo = 0.1; p.nNo = 2;
p.weight = 1;
p.kNi = 1; p.kNa = 1; p.kNb = 1; p.kout = 1;

% State order: M1,Y1,M2,Y2,C,Cs,Ni,Na,Nb,out, four linear references.
% References do not enter the physical-state equations.
initialState = cascade_equilibrium(u_ref,p);
counter_base = initialState(5);
nn_base = initialState(7:10);
gate_base = counter_active_fraction(Y1_ref,Y2_ref,p);
atol = [max(1e-15,abs(initialState(1:10))*1e-9); ...
        max(1e-15,initialState(1)*1e-9); ...
        max(1e-15,Y1_ref*1e-9); ...
        max(1e-15,initialState(3)*1e-9); ...
        max(1e-15,Y2_ref*1e-9)];
maxStep = min([tau_Y1,tau_Y2,1])/2;
odeOptions = odeset('RelTol',1e-7,'AbsTol',atol, ...
    'NonNegative',1:10,'MaxStep',maxStep);

if RUN_SELF_CHECKS %[output:group:70edd964]
    run_cascade_checks(p,odeOptions); %[output:61ab86c5]
end %[output:group:70edd964]
inputFcn = @(s) interp1(t,m_in,s,'linear','extrap');
[~,state] = ode15s(@(s,z) cascade_rhs(s,z,inputFcn,p),t,initialState,odeOptions);
assert(all(isfinite(state(:))), 'Nonfinite simulation result.');
assert(all(all(state(:,1:10) >= -10*atol(1:10).')), ...
    'Negative physical concentrations: check solver and rate calibration.');

% -------- Physical concentrations and actual reaction rates --------
m_M1 = state(:,1); m_Y1 = state(:,2);
m_M2 = state(:,3); m_Y2 = state(:,4);
m_c = state(:,5); m_Cs = state(:,6);
m_Ni = state(:,7); m_Na = state(:,8);
m_Nb = state(:,9); m_out = state(:,10);
enzyme_active = counter_active_fraction(m_Y1,m_Y2,p);
v_Cp_arr = p.VCp*enzyme_active;
v_Cr_arr = p.VCr*enzyme_active.*m_Cs./(p.KCrCs+m_Cs);
v_Cg_arr = p.VCg*m_c./(p.KCgc+m_c).*m_Cs./(p.KCgCs+m_Cs);
m_Cs_arr = m_Cs;
v_11 = p.a1*m_in; v_12 = p.b1*m_M1; v_13 = p.c1*m_in.*m_Y1;
v_21 = p.a2*m_Y1; v_22 = p.b2*m_M2; v_23 = p.c2*m_Y1.*m_Y2;

% -------- Diagnostics ONLY: neither subtraction nor reference feeds a rate --------
d1_deviation = m_Y1-Y1_ref;
d2_deviation = m_Y2-Y2_ref;
enable_concentration_ref = max(-d2_deviation,0);
gate2_ref = m_Y2 < Y2_ref*(1-gate_reference_rel_tol);
if use_first_stage_activation
    gate2_ref = gate2_ref & m_Y1 > Y1_ref*(1+gate_reference_rel_tol);
end
time_count_ref = [0; cumsum(diff(t).*double(gate2_ref(1:end-1)))];
negativeSlope = -gradient(m_in,t);
curvature_ref = gradient(negativeSlope,t); % positive while falling slope builds
first_local_derivative_ref = Y1_ref*tau_M1/u_ref*negativeSlope;
second_local_derivative_ref = Y2_ref*tau_M2/Y1_ref*gradient(m_Y1,t);
first_filtered_ref = state(:,12);
second_filtered_enable_ref = -state(:,14);
counter_deviation = m_c-counter_base;
fprintf('Stage 1 relative deviation range: [%+.4g, %+.4g].\n', ... %[output:group:8dcd2335] %[output:3172f165]
    min(d1_deviation)/Y1_ref,max(d1_deviation)/Y1_ref); %[output:group:8dcd2335] %[output:3172f165]
fprintf('Stage 2 relative deviation range: [%+.4g, %+.4g].\n', ... %[output:group:61d17a0b] %[output:9e5deb6d]
    min(d2_deviation)/Y2_ref,max(d2_deviation)/Y2_ref); %[output:group:61d17a0b] %[output:9e5deb6d]
fprintf('Counter baseline %.4g mM; analog deviation range [%+.4g, %+.4g] mM.\n', ... %[output:group:33e2473d] %[output:8e6ce7cc]
    counter_base,min(counter_deviation),max(counter_deviation)); %[output:group:33e2473d] %[output:8e6ce7cc]
fprintf('Digital enabled-time diagnostic %.4g s; this is NOT the chemical C output.\n', ... %[output:group:796c9c65] %[output:62709990]
    time_count_ref(end)); %[output:group:796c9c65] %[output:62709990]

% Workspace compatibility names: aliases, not additional species/reactions.
m_d = m_Y1; m_d2 = m_Y2;
m_S1 = m_M1; m_F1 = m_Y1;
m_S2 = m_M2; m_F2 = m_Y2;
m_d_target = first_filtered_ref;
m_d2_encoded = -d2_deviation;

% ===================== SAME 13 FIGURE ROLES =====================
shortWindow = [0,min(50,t(end))];

% 1. Original vesicle traces, with finite-difference slope inset.
figure; %[output:084e4351]
idx = unique(round(linspace(1,size(vesicles,1),min(3,size(vesicles,1)))));
plot(t/60,vesicles(idx,:).','LineWidth',2); grid on; %[output:084e4351]
xlabel('Time [min]'); ylabel('Released vesicles'); %[output:084e4351]
labels = arrayfun(@(i) sprintf('d = %.3g um',dist(i)*1e6),idx,'UniformOutput',false);
legend(labels,'Location','southwest','NumColumns',numel(idx)); %[output:084e4351]
set(gca,'FontSize',fontsize); %[output:084e4351]
positionMain = get(gca,'Position');
inset = axes('Position',[positionMain(1)+0.43 positionMain(2)+0.42 0.30 0.26]); %[output:084e4351]
total = min(500,N-1);
plot(t(1:total),diff(vesicles(idx,1:total+1),1,2).'/dtInput,'LineWidth',1.5); %[output:084e4351]
ylabel('Slope [vesicles/s]'); grid on; %[output:084e4351]
set(inset,'FontSize',max(8,fontsize-2)); %[output:084e4351]
if isDemo, title('Synthetic demonstration'); end

% 2. First-stage physical output, short time window, with its baseline.
figure; %[output:3874496c]
plot(t/60,m_Y1,'LineWidth',2); hold on; %[output:3874496c]
yline(Y1_ref,'--','Basal Y1'); grid on; %[output:3874496c]
xlabel('Time [min]'); ylabel('Y_1 concentration [mM]'); %[output:3874496c]
xlim([0,min(5,t(end)/60)]); set(gca,'FontSize',fontsize+4); %[output:3874496c]

% 3. Received input concentration.
figure; %[output:9ddcacbb]
plot(t/60,m_in,'LineWidth',2); grid on; %[output:9ddcacbb]
xlabel('Time [min]'); ylabel('Input concentration [mM]'); %[output:9ddcacbb]
legend(sprintf('d = %.3g um',dist(row)*1e6),'Location','southwest'); %[output:9ddcacbb]
set(gca,'FontSize',fontsize+4); %[output:9ddcacbb]

% 4. Memory and physical output; different concentration scales are real.
figure; %[output:39fd2017]
plot(t/60,m_M1,'LineWidth',2); hold on; %[output:39fd2017]
plot(t/60,m_Y1,'LineWidth',2); grid on; %[output:39fd2017]
xlabel('Time [min]'); ylabel('Concentration [mM]'); %[output:39fd2017]
legend('M_1: memory','Y_1: output','Location','best'); set(gca,'FontSize',fontsize+4); %[output:39fd2017]

% 5. First-stage output across the full recording.
figure; %[output:203778b2]
plot(t/60,m_Y1,'LineWidth',2); hold on; yline(Y1_ref,'--'); grid on; %[output:203778b2]
xlabel('Time [min]'); ylabel('Y_1 concentration [mM]'); %[output:203778b2]
legend('Y_1','Basal Y_1','Location','best'); set(gca,'FontSize',fontsize+4); %[output:203778b2]

% 6. Stage-2 enabling deviation and DIGITAL duration diagnostic.
figure; %[output:2c815491]
yyaxis left; plot(t,enable_concentration_ref,'LineWidth',2); %[output:2c815491]
ylabel('Positive (Y_{2,0}-Y_2), diagnostic [mM]'); %[output:2c815491]
yyaxis right; plot(t,time_count_ref,'--','LineWidth',2); %[output:2c815491]
ylabel('Digital enabled-time reference [s]'); %[output:2c815491]
xlabel('Time [s]'); xlim(shortWindow); grid on; %[output:2c815491]

% 7. Independent linearized stage-2 reference, not a duplicate alias.
figure; %[output:4154af37]
plot(t,-d2_deviation,'b',t,second_filtered_enable_ref,'r--','LineWidth',1.5); %[output:4154af37]
xlabel('Time [s]'); ylabel('Stage-2 enabling deviation [mM]'); %[output:4154af37]
legend('Physical Y_{2,0}-Y_2','Linearized isolated-cascade reference'); %[output:4154af37]
xlim(shortWindow); grid on; %[output:4154af37]

% 8. First-stage deviation against digital input slope.
figure; %[output:90d31afe]
yyaxis left; plot(t,d1_deviation,'LineWidth',2); %[output:90d31afe]
ylabel('Y_1-Y_{1,0}, diagnostic [mM]'); %[output:90d31afe]
yyaxis right; plot(t,negativeSlope,'--','LineWidth',2); %[output:90d31afe]
ylabel('-dm_{in}/dt [mM/s]'); xlabel('Time [s]'); %[output:90d31afe]
legend('Physical output deviation','Digital slope reference'); %[output:90d31afe]
xlim(shortWindow); grid on; %[output:90d31afe]

% 9. First-stage output deviation and its independent filtered reference.
figure; %[output:586464a1]
plot(t,d1_deviation,t,first_filtered_ref,'--','LineWidth',2); %[output:586464a1]
legend('Physical Y_1-Y_{1,0}','Linearized isolated-stage reference'); %[output:586464a1]
xlabel('Time [s]'); ylabel('Output deviation [mM]'); xlim(shortWindow); grid on; %[output:586464a1]

% 10. Memory/output and received input.
figure; %[output:489ec70c]
yyaxis left; plot(t,m_M1,t,m_Y1,'LineWidth',2); %[output:489ec70c]
ylabel('M_1, Y_1 [mM]'); %[output:489ec70c]
yyaxis right; plot(t,m_in,'LineWidth',2); ylabel('Input [mM]'); %[output:489ec70c]
xlabel('Time [s]'); legend('M_1','Y_1','Input','Location','best'); grid on; %[output:489ec70c]
set(gca,'FontSize',fontsize); %[output:489ec70c]

% 11. Received input and first differentiator physical output.
figure; %[output:843cd1e7]
yyaxis left; plot(t,m_in,'LineWidth',2); ylabel('Input [mM]'); %[output:843cd1e7]
yyaxis right; plot(t,m_Y1,'LineWidth',2); ylabel('Y_1 [mM]'); %[output:843cd1e7]
xlabel('Time [s]'); legend('Input','First-stage output','Location','best'); grid on; %[output:843cd1e7]
title('First differentiator: output around a positive baseline'); %[output:843cd1e7]
set(gca,'FontSize',fontsize); %[output:843cd1e7]

% 12. Chemical counter output; show the basal level explicitly.
figure; %[output:925fd31e]
yyaxis left; plot(t,m_in,'LineWidth',2); ylabel('Input [mM]'); %[output:925fd31e]
yyaxis right; plot(t,m_c,'LineWidth',2); hold on; %[output:925fd31e]
yline(counter_base,'--','Basal counter'); ylabel('Counter C [mM]'); %[output:925fd31e]
xlabel('Time [s]'); legend('Input','Chemical C','Basal C','Location','best'); grid on; %[output:925fd31e]
title('Baseline-regulated analog counter'); set(gca,'FontSize',fontsize); %[output:925fd31e]

% 13. Original NN response figure.
figure; %[output:1f19b354]
plot(t,[m_c,m_Ni,m_Na,m_Nb,m_out],'LineWidth',2); grid on; %[output:1f19b354]
xlabel('Time [s]'); ylabel('Concentration [mM]'); %[output:1f19b354]
legend('C: NN input','N_i','N_a','N_b','NN output','Location','best'); %[output:1f19b354]
title('NN block: chemical counter input'); set(gca,'FontSize',fontsize); %[output:1f19b354]

% ========================== HELPERS ==========================
function pathFound = locate_local_file(name,scriptDir)
    pathFound = which(name);
    if ~isempty(pathFound), return; end
    candidates = {fullfile(scriptDir,name),fullfile(pwd,name), ...
                  fullfile(scriptDir,'..','upload',name)};
    for k = 1:numel(candidates)
        if isfile(candidates{k}), pathFound = candidates{k}; return; end
    end
    pathFound = '';
end

function h = hill_activation(x,K,n)
    % Logistic evaluation avoids overflow for large x/K.
    ratio = max(x,0)./K;
    h = 1./(1+exp(-n*log(ratio)));
end

function g = counter_active_fraction(y1,y2,p)
    g = 1-hill_activation(y2,p.Kgate2,p.ngate2);
    if p.use_first_stage_activation
        g = g.*hill_activation(y1,p.Kgate1,p.ngate1);
    end
end

function z0 = cascade_equilibrium(u,p)
    assert(u > 0 && isfinite(u),'Equilibrium input must be positive.');
    m1 = p.a1*u/p.b1;
    y2 = p.a2/p.c2;
    y1 = p.a1*u/(p.c1*u+2*p.consume_interstage*p.a2);
    m2 = p.a2*y1/p.b2;
    g0 = counter_active_fraction(y1,y2,p);
    j0 = p.VCp*g0;
    assert(j0 < p.ksupply*p.Csbase, ...
        'Basal counter source exceeds reset supply: recalibrate counter.');
    residual = @(cs) p.ksupply*(p.Csbase-cs) ...
        - p.VCr*g0*cs/(p.KCrCs+cs)-j0;
    cs0 = fzero(residual,[0,p.Csbase]);
    resetCapacity = p.VCg*cs0/(p.KCgCs+cs0);
    assert(j0 < resetCapacity, ...
        'Basal counter production exceeds reset capacity.');
    c0 = p.KCgc*j0/(resetCapacity-j0);
    ni0 = p.VNi*hill_activation(c0,p.KNi,p.nNi)/p.kNi;
    na0 = p.VNa*hill_activation(ni0,p.KNa,p.nNa)/p.kNa;
    nb0 = p.VNb*hill_activation(ni0,p.KNb,p.nNb)/p.kNb;
    out0 = p.VNo*hill_activation(p.weight*(na0+nb0),p.KNo,p.nNo)/p.kout;
    z0 = [m1;y1;m2;y2;c0;cs0;ni0;na0;nb0;out0;zeros(4,1)];
end

function dz = cascade_rhs(s,z,inputFcn,p)
    u = inputFcn(s);
    assert(isfinite(u) && u > 0,'Adaptive input must remain positive.');
    % Nonnegative rate evaluation during internal implicit solver iterations.
    % Signed linear reference states are deliberately not clipped.
    q = max(z(1:10),0);
    m1=q(1); y1=q(2); m2=q(3); y2=q(4); c=q(5); cs=q(6);
    v11=p.a1*u; v12=p.b1*m1; v13=p.c1*u*y1;
    v21=p.a2*y1; v22=p.b2*m2; v23=p.c2*y1*y2;
    active=counter_active_fraction(y1,y2,p);
    cp=p.VCp*active;
    cr=p.VCr*active*cs/(p.KCrCs+cs);
    cg=p.VCg*c/(p.KCgc+c)*cs/(p.KCgCs+cs);
    dz=zeros(14,1);
    dz(1)=v11-v12;
    dz(2)=v12-v13-p.consume_interstage*(v21+v23);
    dz(3)=v21-v22;
    dz(4)=v22-v23;
    dz(5)=cp-cg;
    dz(6)=p.ksupply*(p.Csbase-cs)-cr-cg;
    dz(7)=p.VNi*hill_activation(c,p.KNi,p.nNi)-p.kNi*q(7);
    dz(8)=p.VNa*hill_activation(q(7),p.KNa,p.nNa)-p.kNa*q(8);
    dz(9)=p.VNb*hill_activation(q(7),p.KNb,p.nNb)-p.kNb*q(9);
    dz(10)=p.VNo*hill_activation(p.weight*(q(8)+q(9)),p.KNo,p.nNo)-p.kout*q(10);
    % Independent local, isolated-stage reference cascade; diagnostics only.
    alpha1=p.c1*p.Y10;
    du=u-p.u0;
    dz(11)=alpha1*du-p.b1*z(11);
    dz(12)=p.b1*z(11)-alpha1*du-p.c1*p.u0*z(12);
    dz(13)=p.a2*z(12)-p.b2*z(13);
    dz(14)=p.b2*z(13)-p.a2*z(12)-p.c2*p.Y10*z(14);
end

function run_cascade_checks(p,options)
    % Meaningful function checks: stationary basal cascade, then polarity.
    duration=20*max([p.tauM1,p.tauM2,p.tauY1,p.tauY2,1]);
    checkTime=linspace(0,duration,1001)';
    z0=cascade_equilibrium(p.u0,p);
    [~,constant]=ode15s(@(s,z) cascade_rhs(s,z,@(~) p.u0,p), ...
        checkTime,z0,options);
    scales=max(abs(z0(1:10)),1e-14);
    relativeDrift=max(max(abs(constant(:,1:10)-z0(1:10).')./scales.'));
    assert(relativeDrift < 1e-5, ...
        'Constant input caused basal drift in the counter/NN cascade.');
    center=4*max(p.tauM1,p.tauM2);
    width=max(p.tauY1,p.tauY2);
    falling=@(s) p.u0*(1-0.1*0.5*(1+tanh((s-center)/width)));
    zFall=cascade_equilibrium(falling(0),p);
    [~,fall]=ode15s(@(s,z) cascade_rhs(s,z,falling,p),checkTime,zFall,options);
    assert(max(fall(:,2)) > zFall(2)*(1+1e-4), ...
        'First stage did not rise during a falling input.');
    assert(min(fall(:,4)) < zFall(4)*(1-1e-4), ...
        'Second stage did not dip while the first-stage slope signal rose.');
    activeFall=counter_active_fraction(fall(:,2),fall(:,4),p);
    active0=counter_active_fraction(zFall(2),zFall(4),p);
    assert(max(activeFall) > active0, 'Counter regulation has wrong polarity.');
    assert(max(fall(:,5)) > zFall(5)*(1+1e-4), ...
        'Enzyme activation did not increase the physical counter concentration.');
    fprintf('Self-checks passed: constant drift %.3g; fall Y1 peak %+.3g%%, Y2 dip %+.3g%%.\n', ...
        relativeDrift,100*(max(fall(:,2))/zFall(2)-1), ...
        100*(min(fall(:,4))/zFall(4)-1));
end

